//! A minimal JSON reader for the test fixtures (no dependencies), shared by
//! the unit tests that read `engine/tests/fixtures/*.json`: the automation
//! lane fixture (`automation.rs`) and the scale/chord parity fixture
//! (`rack/modules/theory.rs`, generated by `app/src/music/scales.fixture.test.ts`).
//! Objects, arrays, plain strings (no escapes), numbers and `null`. Test-only:
//! it panics on anything else.

#[derive(Debug, Clone)]
pub(crate) enum J {
    Null,
    Num(f64),
    Str(String),
    Arr(Vec<J>),
    Obj(Vec<(String, J)>),
}

impl J {
    pub(crate) fn get(&self, key: &str) -> &J {
        match self {
            J::Obj(o) => &o.iter().find(|(k, _)| k == key).unwrap_or_else(|| panic!("no key {key}")).1,
            _ => panic!("not an object"),
        }
    }
    pub(crate) fn arr(&self) -> &[J] {
        match self {
            J::Arr(a) => a,
            _ => panic!("not an array"),
        }
    }
    pub(crate) fn num(&self) -> f64 {
        match self {
            J::Num(n) => *n,
            _ => panic!("not a number"),
        }
    }
    pub(crate) fn str(&self) -> &str {
        match self {
            J::Str(s) => s,
            _ => panic!("not a string"),
        }
    }
    pub(crate) fn is_null(&self) -> bool {
        matches!(self, J::Null)
    }
}

fn ws(b: &[u8], i: &mut usize) {
    while *i < b.len() && b[*i].is_ascii_whitespace() {
        *i += 1;
    }
}

/// Parse one JSON value starting at `b[*i]`, advancing `*i` past it.
pub(crate) fn value(b: &[u8], i: &mut usize) -> J {
    ws(b, i);
    match b[*i] {
        b'{' => {
            *i += 1;
            let mut o = Vec::new();
            loop {
                ws(b, i);
                if b[*i] == b'}' {
                    *i += 1;
                    return J::Obj(o);
                }
                let k = value(b, i).str().to_string();
                ws(b, i);
                assert_eq!(b[*i], b':');
                *i += 1;
                o.push((k, value(b, i)));
                ws(b, i);
                if b[*i] == b',' {
                    *i += 1;
                }
            }
        }
        b'[' => {
            *i += 1;
            let mut a = Vec::new();
            loop {
                ws(b, i);
                if b[*i] == b']' {
                    *i += 1;
                    return J::Arr(a);
                }
                a.push(value(b, i));
                ws(b, i);
                if b[*i] == b',' {
                    *i += 1;
                }
            }
        }
        b'"' => {
            *i += 1;
            let start = *i;
            while b[*i] != b'"' {
                *i += 1;
            }
            *i += 1;
            J::Str(String::from_utf8(b[start..*i - 1].to_vec()).unwrap())
        }
        b'n' => {
            assert_eq!(&b[*i..*i + 4], b"null");
            *i += 4;
            J::Null
        }
        _ => {
            let start = *i;
            while *i < b.len() && matches!(b[*i], b'-' | b'+' | b'.' | b'e' | b'E' | b'0'..=b'9') {
                *i += 1;
            }
            J::Num(std::str::from_utf8(&b[start..*i]).unwrap().parse().unwrap())
        }
    }
}
